  const barkTex = makeBarkTexture();
  const trunkGeo = new THREE.CylinderGeometry(0.22, 0.42, 9, 8, 3);
  trunkGeo.translate(0, 4.5, 0);
  // slight irregularity
  {
    const p = trunkGeo.attributes.position;
    for (let i = 0; i < p.count; i++) {
      const y = p.getY(i);
      p.setX(i, p.getX(i) + Math.sin(y * 1.3) * 0.06);
      p.setZ(i, p.getZ(i) + Math.cos(y * 0.9) * 0.06);
    }
    trunkGeo.computeVertexNormals();
  }
  const trunkMat = new THREE.MeshStandardMaterial({ map: barkTex, roughness: 0.95, color: 0xd8c8b0 });

  const branchGeo = new THREE.CylinderGeometry(0.05, 0.13, 3.2, 5);
  branchGeo.translate(0, 1.6, 0);

  const leafTex = makeLeafCardTexture();
  const blobGeo = mergeVertices(new THREE.IcosahedronGeometry(1.9, 2));
  { // crumple the blob
    const p = blobGeo.attributes.position;
    for (let i = 0; i < p.count; i++) {
      const f = 0.82 + hash2(i * 3.1, i * 1.7) * 0.42;
      p.setXYZ(i, p.getX(i) * f, p.getY(i) * f * 0.85, p.getZ(i) * f);
    }
    blobGeo.computeVertexNormals();
  }
  const blobMat = new THREE.MeshStandardMaterial({
    color: 0xffffff, roughness: 1,
    emissive: 0x1a2c0c, emissiveIntensity: 0.35
  });
  injectSway(blobMat, 0.12);

  const cardGeo = new THREE.PlaneGeometry(4.6, 4.6);
  const cardMat = new THREE.MeshStandardMaterial({
    map: leafTex, alphaTest: 0.5, side: THREE.DoubleSide, roughness: 1, color: 0xffffff,
    emissive: 0x1a2c0c, emissiveIntensity: 0.4
  });
  injectSway(cardMat, 0.22);

  // split trees into angular sectors (x2 distance rings) so whole groups
  // behind the camera get frustum-culled instead of drawing every tree
  const SECTORS = 12, NEAR_RING = 160;
  const groups = Array.from({ length: SECTORS * 2 }, () => []);
  for (const p of treePositions) {
    const bin = Math.min(SECTORS - 1, Math.floor((Math.atan2(p.z, p.x) + Math.PI) / (Math.PI * 2) * SECTORS));
    groups[bin + (Math.hypot(p.x, p.z) < NEAR_RING ? 0 : SECTORS)].push(p);
  }

  const m = new THREE.Matrix4(), q = new THREE.Quaternion(), v = new THREE.Vector3(), sV = new THREE.Vector3();
  const blobColor = new THREE.Color();

  groups.forEach((group, gi) => {
    if (!group.length) return;
    const far = gi >= SECTORS;
    const blobsPer = 3, cardsPer = far ? 7 : 16, branchesPer = far ? 0 : 3;

    const trunks = new THREE.InstancedMesh(trunkGeo, trunkMat, group.length);
    trunks.castShadow = !far; trunks.receiveShadow = true;
    group.forEach((p, i) => {
      q.setFromEuler(new THREE.Euler(0, p.rot, (Math.random() - 0.5) * 0.06));
      m.compose(v.set(p.x, p.y - 0.25, p.z), q, sV.set(p.s, p.s, p.s));
      trunks.setMatrixAt(i, m);
    });

    let branches = null;
    if (branchesPer) {
      branches = new THREE.InstancedMesh(branchGeo, trunkMat, group.length * branchesPer);
      let bi = 0;
      for (const p of group) {
        for (let j = 0; j < branchesPer; j++) {
          const ang = Math.random() * Math.PI * 2;
          const h = (4.5 + Math.random() * 3) * p.s;
          q.setFromEuler(new THREE.Euler((Math.random() * 0.5 + 0.5), ang, 0, 'YXZ'));
          m.compose(v.set(p.x, p.y + h, p.z), q, sV.set(p.s, p.s * (0.7 + Math.random() * 0.5), p.s));
          branches.setMatrixAt(bi++, m);
        }
      }
    }

    const blobs = new THREE.InstancedMesh(blobGeo, blobMat, group.length * blobsPer);
    blobs.castShadow = !far; // canopy shadows come from blobs; cards stay out of the shadow pass
    let fi = 0;
    for (const p of group) {
      for (let j = 0; j < blobsPer; j++) {
        const ang = Math.random() * Math.PI * 2, rr = Math.random() * 1.4 * p.s;
        const h = (6.8 + Math.random() * 2.2) * p.s;
        q.setFromEuler(new THREE.Euler(Math.random(), Math.random() * 6, Math.random()));
        const sc = (0.85 + Math.random() * 0.7) * p.s;
        m.compose(v.set(p.x + Math.cos(ang) * rr, p.y + h, p.z + Math.sin(ang) * rr), q, sV.set(sc, sc, sc));
        blobs.setMatrixAt(fi, m);
        blobColor.setHSL(0.23 + Math.random() * 0.06, 0.40 + Math.random() * 0.18, 0.22 + Math.random() * 0.10);
        blobs.setColorAt(fi, blobColor);
        fi++;
      }
    }

    const cards = new THREE.InstancedMesh(cardGeo, cardMat, group.length * cardsPer);
    let ci = 0;
    for (const p of group) {
      for (let j = 0; j < cardsPer; j++) {
        const ang = Math.random() * Math.PI * 2, rr = Math.random() * 2.5 * p.s;
        const h = (6.3 + Math.random() * 3.6) * p.s;
        q.setFromEuler(new THREE.Euler(Math.random() * Math.PI, Math.random() * Math.PI, Math.random() * Math.PI));
        const sc = (0.95 + Math.random() * 0.85) * p.s;
        m.compose(v.set(p.x + Math.cos(ang) * rr, p.y + h, p.z + Math.sin(ang) * rr), q, sV.set(sc, sc, sc));
        cards.setMatrixAt(ci++, m);
      }
    }

    for (const mesh of [trunks, branches, blobs, cards]) {
      if (!mesh) continue;
      mesh.computeBoundingSphere(); // enables per-sector frustum culling
      scene.add(mesh);
    }
  });
}
